begin
  if (select count(*) from public.reading_texts where source = 'claude_reading_a0_v1') < 20 then
    raise exception 'Спершу запустіть 20261015_reading_a0_v1.sql';
  end if;

  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  select 'reading_text', r.id, r.version,
         jsonb_build_object('code', r.code, 'questions', r.questions, 'glossary', r.glossary, 'known_ratio', r.known_ratio),
         'reading_a0_questions 2026-10-15: RD-A0-001 — варіанти відповідей хорватською (знайти напис на вивісці), запит власника. Бета.'
  from public.reading_texts r
  join jsonb_to_recordset(v_data) as g(code text, glossary jsonb, questions jsonb, known_ratio numeric) on g.code = r.code
  where r.source = 'claude_reading_a0_v1' and (r.glossary is distinct from g.glossary or r.questions is distinct from g.questions)
  on conflict (entity_type, entity_id, version) do nothing;

  with changed as (
    update public.reading_texts r
       set glossary = g.glossary, questions = g.questions, known_ratio = g.known_ratio, version = r.version + 1
      from jsonb_to_recordset(v_data) as g(code text, glossary jsonb, questions jsonb, known_ratio numeric)
     where g.code = r.code and r.source = 'claude_reading_a0_v1'
       and (r.glossary is distinct from g.glossary or r.questions is distinct from g.questions)
    returning r.id, r.status
  ), logged as (
    insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
    select 'reading_text', c.id, c.status, c.status, 'auto_passed', 'ai', '[]'::jsonb, 'reading_a0_questions 2026-10-15: RD-A0-001 — варіанти відповідей хорватською (знайти напис на вивісці), запит власника. Бета.'
    from changed c
    returning 1
  )
  select count(*) into v_changed from logged;

  select count(*) into v_same
    from public.reading_texts r
    join jsonb_to_recordset(v_data) as g(code text, glossary jsonb, questions jsonb, known_ratio numeric) on g.code = r.code
   where r.glossary = g.glossary and r.questions = g.questions;
  if v_same < 20 then raise exception 'Оновлено текстів %, очікувалось 20', v_same; end if;
  raise notice 'Готово: тексти A0 відповідають поточним даним (змінено текстів зараз: %)', v_changed;
end
